<?php
declare(strict_types=1);

require_once __DIR__ . '/config/storefront_role_bridge.php';
require_once __DIR__ . '/config/customer_membership_quote.php';

$error=null;$success=null;$o=[];$customers=[];$user=[];$csrf='';$orderMembership=null;
$id=(int)($_GET['id']??$_POST['id']??0);
$canManage=false;$home='index.php';

try{
    $pdo=role_portal_db();
    srb_ensure($pdo);cm_ensure($pdo);
    $ctx=ps23_admin_ensure($pdo);
    $user=ps23_guard($pdo,'storefront.view');
    $orgId=(int)$ctx['organization_id'];
    $canManage=security_step17_has_permission($pdo,'storefront.manage',$user);
    $home=(string)($user['role_code']??'')==='coach'?'../coach_portal.php':'index.php';
    $csrf=security_step17_csrf();

    if($_SERVER['REQUEST_METHOD']==='POST'){
        if(!$canManage)throw new RuntimeException('This role has view-only access to product order requests.');
        security_step17_verify_csrf((string)($_POST['csrf']??''));
        $action=(string)($_POST['action']??'');
        if($action==='status'){
            ps23_set_status($pdo,$orgId,$id,(string)($_POST['status']??''),(string)($_POST['note']??''),(int)$user['id']);
            $success='Order request status updated.';
        }elseif($action==='link_customer'){
            ps23_link_customer($pdo,$orgId,$id,(int)($_POST['customer_id']??0),(int)$user['id']);
            $success='Customer linked explicitly.';
        }elseif($action==='create_quote'){
            $qid=cm_create_request_quote($pdo,$orgId,$id,(int)$user['id']);
            $success='Internal customer-price quote created: #'.$qid.'.';
        }
    }

    $o=ps23_order($pdo,$orgId,$id);
    if(!empty($o['customer_membership_id'])){
        $s=$pdo->prepare("SELECT m.member_code,m.membership_status,l.label_name,l.badge_text,l.pricing_tier_code,c.full_name coach_name FROM customer_membership_profiles m LEFT JOIN customer_discount_labels l ON l.id=m.discount_label_id LEFT JOIN system_users c ON c.id=m.coach_user_id WHERE m.organization_id=? AND m.id=? LIMIT 1");
        $s->execute([$orgId,(int)$o['customer_membership_id']]);$orderMembership=$s->fetch()?:null;
    }
    if($canManage && ps23_table($pdo,'crm_customers')){
        $s=$pdo->prepare("SELECT id,customer_name,mobile FROM crm_customers WHERE organization_id=? AND status='active' ORDER BY customer_name LIMIT 1000");
        $s->execute([$orgId]);$customers=$s->fetchAll();
    }
}catch(Throwable $e){$error=$e->getMessage();}
$productTotal=max(0,(float)($o['subtotal_mrp']??0)-(float)($o['discount_amount']??0));
?>
<!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Public Order Detail - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><link rel="stylesheet" href="assets/workspace_refresh.css"><style>.pricing-card{padding:13px;border:1px solid #dce8e1;border-radius:14px;background:linear-gradient(135deg,#f3fbf6,#fffaf0);margin-top:12px}.pricing-card .badge{display:inline-flex;padding:5px 8px;border-radius:999px;background:#173f2e;color:#fff;font-size:.58rem;font-weight:900}.pricing-card b{color:#173c2c}.pricing-card small{display:block;margin-top:5px;color:#687a70}.price-old{text-decoration:line-through;color:#8a9991}.price-good{color:#176f45;font-weight:850}</style></head><body>
<header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="public_order_center.php"><img src="../img/logo.png" alt="Healthcare Wellness Club"><span><strong>Healthcare Wellness Club</strong><small>Customer Product Request 360</small></span></a><div class="os-top-actions"><a class="os-btn" href="customer_membership_manager.php">Club Members</a><a class="os-btn" href="public_order_center.php">Order Queue</a><?php if($canManage&&!empty($o['quote_id'])):?><a class="os-btn" href="product_quote_detail.php?id=<?=(int)$o['quote_id']?>">Open Quote</a><?php endif;?><a class="os-btn primary" href="<?=$home?>">My Portal</a></div></div></header>
<main class="os-main" style="max-width:1450px;margin:18px auto 60px;padding:0 12px"><section class="os-hero pp-hero"><div class="os-kicker">CUSTOMER ORDER REQUEST</div><h1><?=ps23_h($o['order_code']??'Order request')?></h1><p>Review the customer request, server-verified pricing context and availability snapshot. Club Member price labels are preserved from checkout; a later staff quote must not silently revert the request to MRP.</p><div class="os-status-row"><?php if($o):?><span class="os-chip good"><?=ps23_h(strtoupper(str_replace('_',' ',(string)$o['order_status'])))?></span><span class="os-chip"><?=ps23_h($o['created_at'])?></span><span class="os-chip"><?=ps23_h($o['discount_label_code']?:strtoupper(str_replace('_',' ',(string)($o['customer_price_mode']??'MRP'))))?></span><span class="os-chip"><?=ps23_money($o['discount_amount']??0)?> discount</span><span class="os-chip"><?=$canManage?'MANAGE ACCESS':'COACH VIEW-ONLY'?></span><?php endif;?></div></section>
<?php if($error):?><div class="pp-alert bad" style="margin-top:14px"><?=ps23_h($error)?></div><?php endif;?><?php if($success):?><div class="pp-alert good" style="margin-top:14px"><?=ps23_h($success)?></div><?php endif;?>
<?php if($o):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-8"><div class="os-title-row"><div><h2>Customer Request</h2><p>Customer contact, member context and delivery preference captured with this request.</p></div></div><div class="pp-source"><b><?=ps23_h($o['customer_name'])?></b><span><?=ps23_h($o['mobile'])?><?=!empty($o['email'])?' • '.ps23_h($o['email']):''?></span></div><div class="pp-source"><b>Delivery</b><span><?=ps23_h(ucwords(str_replace('_',' ',$o['delivery_mode'])))?> • <?=ps23_money($o['delivery_charge'])?><?=($o['delivery_mode']==='home_delivery'?' • '.((float)$o['total_vp']<100?'below 100 VP':'100+ VP'):'')?></span></div><?php if($orderMembership):?><div class="pricing-card"><span class="badge"><?=ps23_h($orderMembership['badge_text']?:$orderMembership['label_name'])?></span><div style="margin-top:8px"><b>Club Member ID: <?=ps23_h($orderMembership['member_code'])?></b><small>Exact price tier: <?=ps23_h($orderMembership['pricing_tier_code']?:'—')?> • Assigned Coach: <?=ps23_h($orderMembership['coach_name']?:'Administrator managed')?> • Membership snapshot ID #<?=(int)$o['customer_membership_id']?></small></div></div><?php else:?><div class="pricing-card"><span class="badge">REGULAR CUSTOMER</span><div style="margin-top:8px"><b><?=ps23_h(ucwords(str_replace('_',' ',(string)($o['customer_price_mode']??'public_mrp'))))?></b><small>No verified Club Member profile was attached to this request.</small></div></div><?php endif;?><?php if(!empty($o['address_text'])):?><div class="pp-source"><b>Address</b><span><?=ps23_h($o['address_text'])?> <?=ps23_h($o['postal_code']??'')?></span></div><?php endif;?><?php if(!empty($o['customer_note'])):?><div class="pp-source"><b>Customer Note</b><span><?=ps23_h($o['customer_note'])?></span></div><?php endif;?><h2 style="margin-top:18px">Product & Pricing Snapshot</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Stock</th><th>Product</th><th>Qty</th><th>MRP</th><th>Customer Price</th><th>Discount</th><th>VP</th><th>Pricing Source</th><th>Availability</th></tr></thead><tbody><?php foreach($o['items'] as $i):$lineCustomer=$i['line_customer_price']!==null?(float)$i['line_customer_price']:(float)$i['line_mrp'];?><tr><td><?=ps23_h($i['stock_no'])?></td><td><?=ps23_h($i['product_name_snapshot'])?></td><td><?=ps23_h($i['quantity'])?></td><td class="<?=((float)$lineCustomer<(float)$i['line_mrp'])?'price-old':''?>"><?=ps23_money($i['line_mrp'])?></td><td class="price-good"><?=ps23_money($lineCustomer)?></td><td><?=ps23_money($i['discount_amount']??max(0,(float)$i['line_mrp']-$lineCustomer))?></td><td><?=ps23_h($i['line_vp'])?></td><td><?=ps23_h($i['pricing_source']?:'MRP')?><?=!empty($i['promotion_code'])?' • '.ps23_h($i['promotion_code']):''?></td><td><?=ps23_h(ucwords(str_replace('_',' ',(string)$i['availability_status'])))?></td></tr><?php endforeach;?></tbody></table></div><div class="pp-alert" style="margin-top:12px">A product marked unavailable/limited here was still allowed as a <b>request</b>. Final allocation must be confirmed before sale finalization. Saved customer/member prices are request snapshots, not permission to alter source price tables.</div></article>
<aside class="os-card pp-span-4"><h2>Request Summary</h2><div class="pp-total"><span>MRP subtotal</span><strong><?=ps23_money($o['subtotal_mrp'])?></strong></div><div class="pp-total"><span>Customer discount</span><strong class="price-good">− <?=ps23_money($o['discount_amount']??0)?></strong></div><div class="pp-total"><span>Product total</span><strong><?=ps23_money($productTotal)?></strong></div><div class="pp-total"><span>Total VP</span><strong><?=ps23_h($o['total_vp'])?></strong></div><div class="pp-total"><span>Delivery</span><strong><?=ps23_money($o['delivery_charge'])?></strong></div><div class="pp-total pp-grand"><span>Estimated total</span><strong><?=ps23_money($o['estimated_total'])?></strong></div><div class="pp-alert" style="background:#fff7ea;color:#805a20">Home delivery rule captured by checkout: below 100 VP = ₹118; 100 VP or more = ₹0. Tax status: <?=ps23_h(str_replace('_',' ',$o['tax_status']))?>. Payment: <?=ps23_h(str_replace('_',' ',$o['payment_status']))?>.</div>
<?php if($canManage):?><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?=ps23_h($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="status"><label>Status<select name="status"><?php foreach(['submitted','reviewing','confirmed','quote_ready','converted','cancelled'] as $s):?><option value="<?=$s?>" <?=$o['order_status']===$s?'selected':''?>><?=ps23_h(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach;?></select></label><label>Internal note<textarea name="note"><?=ps23_h($o['internal_note']??'')?></textarea></label><button>Update Status</button></form><form method="post" class="pp-form" style="margin-top:10px"><input type="hidden" name="csrf" value="<?=ps23_h($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="link_customer"><label>Explicit Customer Link<select name="customer_id" required><option value="">Choose existing customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=$o['customer_id']==$c['id']?'selected':''?>><?=ps23_h($c['customer_name'].(!empty($c['mobile'])?' • '.$c['mobile']:''))?></option><?php endforeach;?></select></label><button>Link Customer</button></form><?php if(empty($o['quote_id'])):?><form method="post" style="margin-top:10px"><input type="hidden" name="csrf" value="<?=ps23_h($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="create_quote"><button class="os-btn primary" style="width:100%">Create Customer-Price Quote</button></form><?php else:?><div class="pp-alert good" style="margin-top:10px">Quote <?=ps23_h($o['quote_code']??('#'.$o['quote_id']))?> is linked and was created from the saved customer pricing snapshot.</div><?php endif;?><?php else:?><div class="pp-alert" style="margin-top:12px"><b>Coach view-only:</b> review member label, product price/discount, VP and delivery; coordinate with the Administrator for availability, quote and finalization.</div><?php endif;?></aside>
<article class="os-card pp-span-12"><div class="os-title-row"><div><h2>Audit Trail</h2><p>Public submission and staff lifecycle events.</p></div></div><?php foreach($o['events'] as $e):?><div class="pp-source"><b><?=ps23_h(ucwords(str_replace('_',' ',$e['event_type'])))?></b><span><?=ps23_h($e['created_at'])?><?=!empty($e['actor_name'])?' • '.ps23_h($e['actor_name']):''?><?=!empty($e['note'])?' • '.ps23_h($e['note']):''?></span></div><?php endforeach;?></article></section><?php endif;?></main></body></html>
